const icon=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const navs=[['home','学习空间','home'],['practice','开始刷题','book'],['review','记忆计划','brain'],['wrong','错题集','file'],['stars','我的收藏','star'],['stats','学习足迹','chart'],['eggs','灵感实验室','spark'],['skins','主题外观','palette'],['settings','偏好设置','settings']];
const defaults={theme:0,font:'sans',fontSize:19,particles:false,particleAmount:26,glow:0.3,brightness:1,bgOpacity:.16,background:'',customAccent:'',customBg:'',customSurface:'',soundRight:false,soundWrong:false,rightSound:'chime',wrongSound:'soft',volume:.4,goal:30,autoNext:false,autoDelay:2,quickSeconds:8,quickReveal:3,reduceMotion:false,optionShuffle:false};
let BANK=[],DEPTS=[],state,view='home',cfg={mode:'sequence',numbering:'department',dept:'全部部门',type:'全部题型',from:1,to:2957,count:30,shuffle:false,single:15,multiple:10,judge:5,examMinutes:30},session=null,timer=null,autoTimer=null,toastTimer,particleFrame,bankPage=1,bankFilter={search:'',dept:'全部部门',type:'全部题型'},skinFilter='',skinCategory='all';
try{state=JSON.parse(localStorage.getItem('zhiyi.v1'))||{}}catch{state={}}state={stats:{},days:{},history:[],settings:{},...state};state.settings={...defaults,...state.settings};
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function save(){try{localStorage.setItem('zhiyi.v1',JSON.stringify(state))}catch{toast('保存空间不足，请先导出学习备份。')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
const qs=id=>state.stats[id]||fresh();const totalAttempts=()=>Object.values(state.stats).reduce((a,s)=>a+s.right+s.wrong,0);const dueIds=()=>BANK.filter(q=>qs(q.id).due&&qs(q.id).due<=Date.now()&&!qs(q.id).mastered);const wrongQs=()=>BANK.filter(q=>qs(q.id).wrong>0&&!qs(q.id).mastered);const pct=(a,b)=>b?Math.round(a/b*100):0;
function fmtDue(t){if(!t)return'尚未安排';const m=Math.ceil((t-Date.now())/60000);if(m<=0)return'现在复习';if(m<60)return`${m} 分钟后`;if(m<1440)return`${Math.ceil(m/60)} 小时后`;return`${Math.ceil(m/1440)} 天后`}
function streakDays(){let n=0,d=new Date();if(!state.days[dateKey(d)]?.count)d.setDate(d.getDate()-1);while(state.days[dateKey(d)]?.count){n++;d.setDate(d.getDate()-1)}return n}
function metrics(){const values=Object.values(state.stats),attempts=totalAttempts(),right=values.reduce((a,s)=>a+s.right,0);return{attempts,right,seen:values.filter(s=>s.right+s.wrong>0).length,mastered:values.filter(s=>s.mastered).length,accuracy:pct(right,attempts),today:state.days[dateKey()]?.count||0,due:dueIds().length,wrong:wrongQs().length}}
function stat(label,value,unit,note,ico){return`<div class="stat"><div class="stat-top">${label}${icon(ico)}</div><div class="stat-number">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`}
function heading(title,sub,action='',eyebrow=''){return`<div class="heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function navigate(v){clearInterval(timer);clearTimeout(autoTimer);document.body.classList.remove('menu-open');if(v!=='study')document.body.classList.remove('focus');view=v;bankPage=1;render();window.scrollTo(0,0)}
function render(){const active=view==='study'?'practice':view;const skin=SKINS[state.settings.theme]||SKINS[0];$('#app').innerHTML=`<div class="mobile-backdrop" data-action="menu"></div><div class="shell"><aside class="sidebar"><button class="brand" data-nav="home"><span class="brandmark">${icon(skin.symbol)}</span><span><span class="brand-name">知一</span><br><small>ZHIYI · STUDY</small></span></button><div class="nav-title">学习</div>${navs.slice(0,6).map(([id,name,ico])=>`<button class="nav ${active===id?'active':''}" data-nav="${id}">${icon(ico)}${name}${id==='wrong'&&wrongQs().length?`<span class="badge">${wrongQs().length}</span>`:''}</button>`).join('')}<div class="nav-title">探索</div>${navs.slice(6,8).map(([id,name,ico])=>`<button class="nav ${active===id?'active':''}" data-nav="${id}">${icon(ico)}${name}</button>`).join('')}<div class="sidebar-bottom"><button class="nav ${active==='settings'?'active':''}" data-nav="settings">${icon('settings')}偏好设置</button><div class="local-card"><strong>${icon('shield')} 学习记录已在本机保存</strong>备份后可在其他设备继续学习<button class="link" data-action="export" style="display:block;margin-top:7px;padding:0">导出学习备份 ${icon('arrow')}</button></div></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn icon-only mobile-menu" data-action="menu" aria-label="打开菜单">${icon('menu')}</button><strong>我的学习空间</strong><span>/</span><span>${navs.find(n=>n[0]===active)?.[1]||'开始刷题'}</span></div><div class="topbar-actions"><span class="date-label">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span><button class="btn icon-only" data-action="help" aria-label="使用帮助">${icon('help')}</button><button class="avatar" data-nav="settings" aria-label="偏好设置">知</button></div></header><div class="content" id="content">${renderView()}</div></main></div>`;if(view==='study')startTimer();if(view==='skins')paintSkinPreview();}
function renderView(){switch(view){case'home':return home();case'practice':return practice();case'study':return study();case'wrong':case'stars':return questionList();case'review':return review();case'stats':return statsPage();case'eggs':return eggs();case'skins':return skins();case'settings':return settings();default:return home()}}
function home(){const m=metrics(),hour=new Date().getHours(),greeting=hour<11?'早上好':hour<14?'中午好':hour<18?'下午好':'晚上好';return`${heading(`${greeting}，今天也进步一点。`,'从一道题开始，让知识慢慢成为直觉。',btn(`${icon('chart')} 学习报告`,'goto-stats'),'YOUR LEARNING SPACE')}<div class="stats-grid">${stat('今日已练',m.today,'题',`每日目标 ${state.settings.goal} 题`,'sun')}${stat('累计正确率',m.attempts?m.accuracy+'%':'—','',`累计作答 ${m.attempts} 次`,'target')}${stat('已学题目',m.seen.toLocaleString(),' / 2,957',`已覆盖 ${pct(m.seen,BANK.length)}% 的题库`,'book')}${stat('连续学习',streakDays(),'天',streakDays()?'保持节奏，知识正在积累':'今天，是很好的开始','flame')}</div><div class="dashboard-grid"><div class="stack"><section class="panel start-panel"><div class="panel-title"><h2>开始一段专注学习</h2><span class="badge">运营岗位资质</span></div>${configForm(true)}</section><section class="panel"><div class="panel-title"><h2>换一种方式记住</h2><button class="link" data-nav="eggs">探索 20 种玩法 ${icon('arrow')}</button></div><div class="mode-grid">${['loop','flash','quick','game','read','random'].map(id=>{const m=MODES.find(x=>x[0]===id);return`<button class="mode-card" data-mode="${id}"><span class="icon-tile">${icon(m[2])}</span><strong>${m[1]}</strong><p>${({loop:'让错题在合适的时候再见面',flash:'翻一张卡，唤醒一次记忆',quick:'给自己一点时间上的挑战',game:'把每一次答对变成下一关',read:'先理解，再把答案记下来',random:'打破顺序，检验真正的掌握'})[id]}</p></button>`}).join('')}</div></section><section class="panel"><div class="panel-title"><h2>部门学习进度</h2><span class="muted small">已学 / 题目数</span></div>${departments()}</section></div><div class="stack"><section class="panel review-box"><div class="panel-title"><h2>记忆，也需要温习</h2>${icon('brain')}</div><div class="big-number">${m.due}</div><p class="small muted">道题等待今天的你</p><svg viewBox="0 0 240 80" class="memory-curve" aria-label="间隔复习示意曲线"><path d="M0 65H240" stroke="currentColor" stroke-opacity=".15" fill="none"/><path d="M0 10Q20 50 45 62L48 12Q78 46 105 53L108 12Q145 35 171 40L174 12Q210 26 240 28" stroke="currentColor" stroke-width="2" fill="none"/><path d="M48 12V65M108 12V65M174 12V65" stroke="currentColor" stroke-opacity=".15" stroke-dasharray="3 4"/></svg><p class="small muted">在遗忘之前，再见一面。</p>${btn(`${icon('repeat')} 开始到期复习`,'start-review','primary')}<div class="review-timeline"><span><i></i>今天</span><span><i></i>1 天</span><span><i></i>3 天</span><span><i></i>7 天</span><span><i></i>30 天</span></div></section><section class="panel"><div class="panel-title"><h2>每日小目标</h2><button class="link" data-action="goal">调整</button></div><div class="goal-ring" style="--pct:${Math.min(100,pct(m.today,state.settings.goal))}%"><div><strong>${pct(m.today,state.settings.goal)}<small>%</small></strong><small>今日完成</small></div></div><p class="small muted" style="text-align:center">${m.today>=state.settings.goal?'今天的目标完成了，做得不错。':`还差 ${state.settings.goal-m.today} 道题，继续加油。`}</p></section><section class="panel"><div class="panel-title"><h2>属于你的学习空间</h2>${icon('palette')}</div><p class="small muted">56 种主题，换一种心情。<br>无论怎样变化，阅读始终清晰。</p><button class="link" data-nav="skins" style="margin-top:15px;padding:0">挑选你的主题 ${icon('arrow')}</button></section></div></div><div class="bottom-tip">${icon('shield')} 题库来自你上传的文件，答案按原题库保留。学习数据保存在当前浏览器。</div>`}
function departments(){return`<div class="department-list">${DEPTS.map((d,i)=>{const all=BANK.filter(q=>q.dept===d),n=all.filter(q=>qs(q.id).right+qs(q.id).wrong).length;return`<div class="dept-row"><button class="dept-name text-button" data-dept="${esc(d)}"><span class="dept-dot" style="opacity:${.45+i*.07}"></span>${esc(d)}</button><span class="muted">${n} <span style="opacity:.5">/ ${all.length}</span></span><div class="progress-track"><div class="progress-fill" style="width:${pct(n,all.length)}%"></div></div></div>`}).join('')}</div>`}
function selectOptions(vals,current){return vals.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function configForm(compact=false){const mode=MODES.find(m=>m[0]===cfg.mode)||MODES[0],isExam=cfg.mode==='exam';return`<div class="mode-tabs">${(compact?MODES.slice(0,6):MODES).map(m=>`<button class="mode-tab ${cfg.mode===m[0]?'active':''}" data-config-mode="${m[0]}">${icon(m[2])}${m[1]}</button>`).join('')}</div><div class="form-grid"><label class="field">选择部门<select data-cfg="dept">${selectOptions(['全部部门',...DEPTS],cfg.dept)}</select></label><label class="field">题目类型<select data-cfg="type">${selectOptions(['全部题型','单选','多选','判断'],cfg.type)}</select></label><label class="field">题号范围 · ${cfg.dept!=='全部部门'&&cfg.numbering!=='global'?'部门内原题号':'全库统一编号'}<div class="inline" style="flex-wrap:nowrap"><input aria-label="起始题号" type="number" min="1" max="2957" data-cfg="from" value="${cfg.from}"><span class="muted">至</span><input aria-label="结束题号" type="number" min="1" max="2957" data-cfg="to" value="${cfg.to}"></div></label><label class="field">${isExam?'考试时长（分钟）':'每组题数'}<input type="number" min="1" max="${isExam?300:2957}" data-cfg="${isExam?'examMinutes':'count'}" value="${isExam?cfg.examMinutes:cfg.count}"></label>${isExam?`<div class="field full"><span>组卷配比（可填 0；不足时按实际题数抽取）</span><div class="form-grid" style="grid-template-columns:repeat(3,1fr)"><label class="field">单选<input type="number" min="0" max="1119" data-cfg="single" value="${cfg.single}"></label><label class="field">多选<input type="number" min="0" max="863" data-cfg="multiple" value="${cfg.multiple}"></label><label class="field">判断<input type="number" min="0" max="975" data-cfg="judge" value="${cfg.judge}"></label></div></div>`:''}${cfg.mode==='quick'?`<label class="field">作答倒计时（秒）<input type="number" min="2" max="120" data-setting="quickSeconds" value="${state.settings.quickSeconds}"></label><label class="field">答案停留（秒）<input type="number" min="1" max="30" data-setting="quickReveal" value="${state.settings.quickReveal}"></label>`:''}</div>${cfg.dept!=='全部部门'?`<label class="field" style="margin-top:14px">题号口径<select data-cfg="numbering"><option value="department" ${cfg.numbering!=='global'?'selected':''}>部门内题号（原表序号）</option><option value="global" ${cfg.numbering==='global'?'selected':''}>全库统一编号（1—2957）</option></select></label>`:''}<div class="mode-description">${mode[3]}${cfg.mode==='loop'?'<br>按所选题号口径与部门筛选。尚未到期的题可强化练习，但不会提前推进记忆阶段；需跨间隔答对 8 个阶段才标记为掌握。':''}</div><div class="config-footer"><label class="check"><input type="checkbox" data-cfg="shuffle" ${cfg.shuffle?'checked':''}>打乱题目顺序</label>${btn(`开始学习 ${icon('arrow')}`,'start','primary')}</div>`}
function practice(){return`${heading('每次专注，都算数。','选择适合今天的节奏。',session?btn('继续上次练习','resume','soft'):'','PRACTICE')}<section class="panel start-panel">${configForm()}</section><section class="panel" style="margin-top:24px"><div class="panel-title"><h2>题库答题卡</h2><span class="muted small">点击题号可从该题开始</span></div><div class="filters"><input class="search" type="number" min="1" max="2957" id="jump-global" placeholder="输入题号，如 200" aria-label="跳转题号">${btn('前往题目','jump-global')}</div><div class="answer-grid" style="grid-template-columns:repeat(auto-fill,minmax(48px,1fr));max-height:230px">${BANK.filter(q=>cfg.dept==='全部部门'||q.dept===cfg.dept).map(q=>`<button class="answer-number ${qs(q.id).last?(qs(q.id).streak?'ok':'bad'):''}" data-start-id="${q.id}">${q.id}</button>`).join('')}</div></section>`}
function review(){const m=metrics(),stages=Array.from({length:9},(_,i)=>BANK.filter(q=>(qs(q.id).right+qs(q.id).wrong)>0&&qs(q.id).stage===i).length);return`${heading('让记忆，留得更久。','根据实际作答安排下一次复习。',btn(`${icon('repeat')} 复习到期 ${m.due} 题`,'start-review','primary'),'SPACED REPETITION')}<div class="stats-grid">${stat('已到期',m.due,'题','现在适合复习','clock')}${stat('正在巩固',Object.values(state.stats).filter(s=>s.due&&!s.mastered).length,'题','正在间隔复习计划中','brain')}${stat('已掌握',m.mastered,'题','完成 8 个记忆阶段','shield')}${stat('当前错题',m.wrong,'题','未掌握的历史错题','file')}</div><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-title"><h2>你的记忆阶梯</h2><span class="muted small">到期后答对，进入下一阶段</span></div>${['重新学习 · 5 分钟','第 1 阶段 · 30 分钟','第 2 阶段 · 12 小时','第 3 阶段 · 1 天','第 4 阶段 · 3 天','第 5 阶段 · 7 天','第 6 阶段 · 15 天','第 7 阶段 · 30 天','已掌握'].map((s,i)=>`<div class="list-line"><span>${s}</span><strong>${stages[i]} 题</strong></div>`).join('')}</section><section class="panel"><div class="panel-title"><h2>接下来复习什么</h2></div>${BANK.filter(q=>qs(q.id).due&&!qs(q.id).mastered).sort((a,b)=>qs(a.id).due-qs(b.id).due).slice(0,15).map(q=>`<div class="list-line"><button class="text-button" data-start-id="${q.id}"><span class="tag">${q.id}</span> ${esc(q.text.slice(0,43))}${q.text.length>43?'…':''}</button><span class="muted" style="white-space:nowrap">${fmtDue(qs(q.id).due)}</span></div>`).join('')||empty('你的记忆计划尚未开始','完成一次练习后，题目会自动进入计划。','book','start-default')}</section></div><div class="stack"><section class="panel review-box"><h2>间隔比重复次数更重要</h2><p class="small" style="margin-top:16px">同一题在短时间反复答对，能增强熟悉感，但不代表长期掌握。知一只在复习到期后推进阶段。</p><p class="small" style="margin-top:15px">答错后回到 5 分钟复习；完成最后的 30 天复习后，题目退出循环。之后再次答错，自动回归计划。</p><p class="small muted" style="margin-top:15px">这是参考遗忘曲线的固定间隔计划，不是对个人记忆程度的精确测量。</p></section>${btn('设置循环范围','setup-loop','soft')}</div></div>`}
function empty(title,desc,ico='book',action=''){return`<div class="empty">${icon(ico)}<h2>${title}</h2><p>${desc}</p>${action?btn('开始学习',action,'primary'):''}</div>`}
function questionList(){const wrong=view==='wrong';let all=BANK.filter(q=>wrong?(qs(q.id).wrong>0&&!qs(q.id).mastered):qs(q.id).star);all=all.filter(q=>(bankFilter.dept==='全部部门'||q.dept===bankFilter.dept)&&(bankFilter.type==='全部题型'||q.type===bankFilter.type)&&(!bankFilter.search||`${q.id} ${q.text} ${q.options.map(o=>o.text).join('')}`.includes(bankFilter.search)));const pages=Math.max(1,Math.ceil(all.length/20));bankPage=Math.min(bankPage,pages);return`${heading(wrong?'把错过的，变成会的。':'值得再看一遍。',wrong?'每一次错误，都是下一次进步的起点。':'你收藏的题目与知识。',btn(`${icon('repeat')} ${wrong?'重练错题':'练习收藏'}`,wrong?'start-wrong':'start-stars','primary'),wrong?'MISTAKES TO MASTERY':'MY COLLECTION')}<div class="panel"><div class="filters"><input class="search" id="bank-search" value="${esc(bankFilter.search)}" placeholder="搜索题目、选项或题号" aria-label="搜索题库"><select data-filter="dept" aria-label="筛选部门">${selectOptions(['全部部门',...DEPTS],bankFilter.dept)}</select><select data-filter="type" aria-label="筛选题型">${selectOptions(['全部题型','单选','多选','判断'],bankFilter.type)}</select>${btn('搜索','bank-search')}</div>${!all.length?empty(wrong?'这里还没有错题':'还没有收藏题目',wrong?'答错的题会自动收录，完成记忆阶段后移出。':'练习时点击星标，就能把题目留在这里。',wrong?'shield':'star','start-default'):`<div class="table-wrap"><table class="question-table"><thead><tr><th>题号</th><th>题目</th><th>部门 / 题型</th><th>答对 / 答错</th><th>操作</th></tr></thead><tbody>${all.slice((bankPage-1)*20,bankPage*20).map(q=>`<tr><td>${q.id}</td><td><button class="text-button" data-start-id="${q.id}">${esc(q.text)}</button>${qs(q.id).note?`<p class="small muted">笔记：${esc(qs(q.id).note)}</p>`:''}</td><td>${esc(q.dept)}<br><span class="tag">${q.type}</span></td><td>${qs(q.id).right} / ${qs(q.id).wrong}</td><td><button class="btn icon-only" aria-label="${qs(q.id).star?'取消收藏':'收藏'}" data-star="${q.id}" style="color:${qs(q.id).star?'var(--accent)':'inherit'}">${icon('star')}</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>共 ${all.length} 题 · ${bankPage} / ${pages} 页</span><div class="inline">${btn('上一页','bank-prev','',bankPage===1?'disabled':'')}${btn('下一页','bank-next','',bankPage===pages?'disabled':'')}</div></div>`}</div>`}
function statsPage(){const m=metrics(),days=Array.from({length:84},(_,i)=>{const d=new Date();d.setDate(d.getDate()-83+i);return{key:dateKey(d),count:state.days[dateKey(d)]?.count||0}}),week=days.slice(-7),max=Math.max(1,...week.map(d=>d.count));return`${heading('看见每一步成长。','所有数字，都来自你的真实练习。',btn(`${icon('download')} 导出学习备份`,'export'),'LEARNING JOURNAL')}<div class="stats-grid">${stat('累计作答',m.attempts.toLocaleString(),'次',`其中答对 ${m.right} 次`,'book')}${stat('整体正确率',m.attempts?m.accuracy+'%':'—','',`答错 ${m.attempts-m.right} 次`,'target')}${stat('题库覆盖',pct(m.seen,BANK.length)+'%','',`已学 ${m.seen} / ${BANK.length} 题`,'chart')}${stat('长期掌握',m.mastered,'题','完成全部记忆阶段','shield')}</div><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-title"><h2>学习热力图</h2><span class="small muted">最近 84 天 · 作答次数</span></div><div class="heatmap">${days.map(d=>`<div class="heat-cell" title="${d.key}：${d.count} 次" style="${d.count?`background:color-mix(in srgb,var(--accent) ${Math.min(100,20+d.count*2)}%,var(--bg))`:''}"></div>`).join('')}</div><div class="legend"><span>${days[0].key}</span><span style="margin-left:auto">${days.at(-1).key}</span></div></section><section class="panel"><div class="panel-title"><h2>部门学习进度</h2></div>${departments()}</section><section class="panel"><div class="panel-title"><h2>最近完成的练习</h2></div>${state.history.length?state.history.slice(0,12).map(h=>`<div class="list-line"><span>${esc(h.name)}<br><span class="muted small">${new Date(h.time).toLocaleString('zh-CN')}</span></span><span>${h.right} / ${h.total} 答对<br><span class="muted">${pct(h.right,h.total)}% 正确率</span></span></div>`).join(''):empty('还没有完成的练习','完成一组练习后，记录会显示在这里。','chart')}</section></div><div class="stack"><section class="panel"><h2>最近 7 天</h2><div class="chart">${week.map(d=>`<div class="chart-col"><span>${d.count}</span><div class="chart-bar" style="height:${d.count/max*100}px"></div>${d.key.slice(5)}</div>`).join('')}</div></section><section class="panel"><h2>各题型正确率</h2>${['单选','多选','判断'].map(t=>{const ss=BANK.filter(q=>q.type===t).map(q=>qs(q.id)),r=ss.reduce((a,s)=>a+s.right,0),all=ss.reduce((a,s)=>a+s.right+s.wrong,0);return`<div class="q-stats"><span>${t}</span><span>${all?pct(r,all)+'%':'暂无作答'} <small class="muted">${r}/${all}</small></span></div>`}).join('')}</section><section class="panel review-box"><h2>一点点，也是一大步</h2><p class="small" style="margin-top:12px">已坚持 ${Object.keys(state.days).filter(d=>state.days[d].count>0).length} 个学习日。每次主动回忆，都会让下次想起答案更容易。</p></section></div></div>`}
function eggs(){return`${heading('让学习，有一点意外。','20 种有不同规则的小实验。选一个，直接开始。',btn('随机选一种','random-egg','soft'),'THE LEARNING LAB')}<div class="note-banner">所有玩法使用你的真实题库，答题结果计入学习记录。范围沿用“开始刷题”中的部门与题号设置：${esc(cfg.dept)} · ${cfg.from}—${cfg.to}。</div><div class="egg-grid">${EGGS.map((e,i)=>`<button class="egg-card" data-egg="${e[0]}"><div class="egg-number">EXPERIMENT ${String(i+1).padStart(2,'0')}${icon(e[2])}</div><h3>${e[1]}</h3><p>${e[3]}</p></button>`).join('')}</div>`}
function skins(){const found=SKINS.filter(s=>(!skinFilter||s.name.toLowerCase().includes(skinFilter.toLowerCase()))&&(skinCategory==='all'||(skinCategory==='dark'?s.dark:skinCategory==='light'?!s.dark:s.style===skinCategory)));return`${heading('你的空间，你的颜色。','让风格随心情变化，让阅读始终舒适。',btn('恢复默认外观','reset-appearance'),'MAKE IT YOURS')}<div class="settings-layout"><div class="stack"><section class="panel"><div class="panel-title"><h2>主题收藏馆 <span class="badge">56 款</span></h2><span class="small muted">灵感主题 · 非官方联名</span></div><div class="filters"><input id="skin-search" class="search" placeholder="搜索主题，如：像素、水墨、星空" value="${esc(skinFilter)}" aria-label="搜索主题">${btn('搜索','skin-search')}</div><div class="mode-tabs">${[['all','全部'],['light','明亮'],['dark','深色'],['pixel','像素'],['glass','玻璃'],['serif','人文']].map(([v,t])=>`<button class="mode-tab ${skinCategory===v?'active':''}" data-skin-category="${v}">${t}</button>`).join('')}</div><div class="skin-grid">${found.map(s=>`<button class="skin ${s.id===state.settings.theme?'active':''}" data-skin="${s.id}" aria-label="应用${s.name}"><span class="skin-preview" style="background:${s.bg};color:${s.accent};border:1px solid ${s.line};${s.style==='pixel'?'border-radius:0':''}">${icon(s.symbol)}<span class="skin-lines"><i></i><i></i><i></i></span></span><span class="skin-label">${s.name}</span><span class="skin-detail">${PARTICLES[s.particle]} · ${['简洁线形','圆润线形','方角线形'][s.id%3]}图标</span></button>`).join('')}</div>${!found.length?empty('没有找到这个主题','试试另一个关键词。','search'):''}</section></div><div class="settings-stack"><section class="panel"><h2>阅读预览</h2><div id="reading-preview" style="margin-top:14px;border:1px solid var(--line);border-radius:10px;padding:16px"><span class="tag">${icon(SKINS[state.settings.theme]?.symbol)} 知一</span><p class="question-title" style="margin:12px 0;font-size:var(--reading)">学习的意义，在于每一次理解与记住。</p><div class="option selected" style="font-size:14px;margin:0"><span class="option-letter">A</span>清晰，始终是第一位。</div></div><p class="small muted" style="margin-top:10px">题目使用独立阅读底色，粒子不会覆盖文字。</p></section>${appearanceSettings()}<section class="panel"><h2>保存你的搭配</h2><p class="small muted" style="margin:12px 0">主题、调色、字体与背景设置都可备份。</p><div class="inline">${btn('导出主题','export-theme')}${btn('导入主题','import-theme')}</div></section></div></div>`}
function appearanceSettings(){const s=state.settings;return`<section class="panel"><h2>字体与阅读</h2><label class="field">中文字体<select data-setting="font">${[['sans','思源黑体 · 清晰'],['serif','思源宋体 · 书卷'],['system','设备系统字体'],['custom','我上传的字体']].map(([v,t])=>`<option value="${v}" ${s.font===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="link" data-action="upload-font" style="padding:9px 0">上传字体文件（TTF / OTF / WOFF）</button><p class="small muted">内置两套中文字体；自定义字体保存在本机。</p><label class="field">题目字号 <output id="fontSize-label">${s.fontSize}</output> px<input type="range" min="16" max="30" step="1" data-setting="fontSize" value="${s.fontSize}"></label></section><section class="panel"><h2>光与颜色</h2><label class="field">强调色<input type="color" data-setting="customAccent" value="${s.customAccent||toHex(SKINS[s.theme].accent)}"></label><label class="field">页面底色<input type="color" data-setting="customBg" value="${s.customBg||toHex(SKINS[s.theme].bg)}"></label><label class="field">阅读底色<input type="color" data-setting="customSurface" value="${s.customSurface||SKINS[s.theme].surface.startsWith('#')&&SKINS[s.theme].surface||'#ffffff'}"></label><label class="field">显示亮度<input type="range" min="0.65" max="1.15" step="0.01" data-setting="brightness" value="${s.brightness}"></label><label class="field">霓虹光晕<input type="range" min="0" max="1" step="0.01" data-setting="glow" value="${s.glow}"></label><p class="small muted">文字随阅读底色自动切换深浅，保证对比度。</p></section><section class="panel"><h2>背景与粒子</h2><div class="setting-row"><span>主题粒子特效</span><input type="checkbox" aria-label="主题粒子特效" data-setting="particles" ${s.particles?'checked':''}></div><label class="field">粒子数量<input type="range" min="8" max="80" step="1" data-setting="particleAmount" value="${s.particleAmount}"></label><div class="setting-row"><span>减少动态效果</span><input type="checkbox" aria-label="减少动态效果" data-setting="reduceMotion" ${s.reduceMotion?'checked':''}></div><div class="inline" style="margin-top:16px">${btn('上传背景图','upload-bg')}${btn('移除','remove-bg')}</div><label class="field">背景可见度<input type="range" min="0" max="0.8" step="0.01" data-setting="bgOpacity" value="${s.bgOpacity}"></label></section>`}
function settings(){const s=state.settings;return`${heading('找到你的舒适节奏。','答题、声音和设备偏好，都在这里。','','PREFERENCES')}<div class="settings-layout"><div class="stack"><section class="panel"><h2>练习偏好</h2><div class="setting-row"><span>答题后自动跳到下一题</span><input type="checkbox" data-setting="autoNext" aria-label="答题后自动下一题" ${s.autoNext?'checked':''}></div><label class="field" style="margin-top:15px">自动跳题停留秒数<input type="number" min="1" max="30" data-setting="autoDelay" value="${s.autoDelay}"></label><div class="setting-row"><span>打乱选择题选项（不改变原答案映射）</span><input type="checkbox" data-setting="optionShuffle" aria-label="打乱选项" ${s.optionShuffle?'checked':''}></div><label class="field" style="margin-top:15px">每日作答目标<input type="number" min="1" max="2000" data-setting="goal" value="${s.goal}"></label><div class="form-grid" style="margin-top:15px"><label class="field">快答倒计时（秒）<input type="number" min="2" max="120" data-setting="quickSeconds" value="${s.quickSeconds}"></label><label class="field">快答答案停留（秒）<input type="number" min="1" max="30" data-setting="quickReveal" value="${s.quickReveal}"></label></div></section><section class="panel"><div class="panel-title"><h2>答题音效</h2>${icon('volume')}</div><div class="setting-row"><span>开启答对音效</span><input type="checkbox" data-setting="soundRight" aria-label="答对音效" ${s.soundRight?'checked':''}></div><div class="form-grid" style="margin:15px 0"><label class="field">答对声音<select data-setting="rightSound">${[['chime','清脆风铃'],['piano','轻柔琴音'],['arcade','掌机升级'],['water','水滴回响'],['space','星际信号']].map(([v,t])=>`<option value="${v}" ${s.rightSound===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="field"><span>听听看</span>${btn('试听答对音效','preview-right')}</div></div><div class="setting-row"><span>开启答错音效</span><input type="checkbox" data-setting="soundWrong" aria-label="答错音效" ${s.soundWrong?'checked':''}></div><div class="form-grid" style="margin:15px 0"><label class="field">答错声音<select data-setting="wrongSound">${[['soft','轻柔提醒'],['wood','木质敲击'],['arcade','掌机提示'],['low','低音提示'],['space','电波回落']].map(([v,t])=>`<option value="${v}" ${s.wrongSound===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="field"><span>听听看</span>${btn('试听答错音效','preview-wrong')}</div></div><label class="field">音量<input type="range" min="0" max="1" step="0.01" data-setting="volume" value="${s.volume}"></label></section><section class="panel"><h2>学习备份</h2><p class="small muted" style="margin:13px 0 18px">Windows、iPhone、iPad 与安卓独立保存记录。通过导出 / 导入，在设备之间迁移进度。备份包括答题记录、错题、收藏、笔记及设置；自定义字体需单独上传。</p><div class="inline">${btn(`${icon('download')} 导出备份`,'export','primary')}${btn(`${icon('upload')} 导入备份`,'import')}${btn('清空学习记录','clear-data','danger')}</div></section><section class="panel"><h2>安装到主屏幕</h2><div class="read-step"><strong>iPhone / iPad</strong><p class="small muted">在 Safari 打开，点击分享 → 添加到主屏幕。</p></div><div class="read-step"><strong>安卓</strong><p class="small muted">在 Chrome 菜单中选择“安装应用”或“添加到主屏幕”。</p></div><div class="read-step"><strong>Windows</strong><p class="small muted">使用 Edge 或 Chrome，点击地址栏的安装图标。</p></div><p class="small muted" style="margin-top:15px">联网打开并缓存成功后可离线学习。清除浏览器数据会删除本机进度，请定期备份。</p></section></div><div class="settings-stack"><section class="panel review-box"><h2>为每一块屏幕准备</h2><div class="read-step">iPhone / 安卓手机<p class="small muted">单列答题 · 底部导航 · 拇指操作</p></div><div class="read-step">iPad / 安卓平板<p class="small muted">触控大按钮 · 分栏答题卡 · 横竖屏适配</p></div><div class="read-step">Windows / 电脑<p class="small muted">完整侧边栏 · 学习面板 · 快捷键</p></div></section><section class="panel"><h2>键盘快捷键</h2>${[['A—F','选择对应选项'],['Enter','提交答案 / 下一题'],['← / →','上一题 / 下一题'],['S','收藏当前题目'],['Shift+F','切换专注视图'],['Esc','退出专注视图']].map(([a,b])=>`<div class="q-stats"><span>${a}</span><span class="muted">${b}</span></div>`).join('')}</section><section class="panel"><h2>部署与题库</h2><a class="btn" style="margin-top:15px;text-decoration:none" href="./zhiyi-source.zip" download>下载 GitHub 部署包</a><p class="small muted" style="margin-top:13px">运营岗位资质 · 2,957 题<br>单选 1,119 · 多选 863 · 判断 975<br>来自你上传的《题库(1).xlsx》。<br>原文件未提供解析；网站展示原题库答案与个人笔记。</p></section></div></div>`}
function toHex(color){if(color.startsWith('#'))return color;const c=document.createElement('canvas').getContext('2d');c.fillStyle=color;return c.fillStyle}
function luminance(c){c=toHex(c);const a=c.replace('#','').match(/.{2}/g)?.map(x=>parseInt(x,16)/255)||[1,1,1];return a.reduce((v,x,i)=>v+(x<=.04045?x/12.92:((x+.055)/1.055)**2.4)*[.2126,.7152,.0722][i],0)}
function applyTheme(){const s=state.settings,k=SKINS[s.theme]||SKINS[0],r=document.documentElement.style;let surface=s.customSurface||k.surface,accent=s.customAccent||k.accent,dark=luminance(surface)<.35;const vars={accent,'accent-soft':k.soft,bg:s.customBg||k.bg,surface,text:dark?'#f3f6f5':'#202e2c',muted:dark?'#aebcb7':'#657571',line:dark?'#3c4845':'#dce5e1',fontSize:s.fontSize,glow:s.glow,brightness:s.brightness,'bg-opacity':s.bgOpacity,'reading':s.fontSize+'px','bg-image':s.background?`url("${s.background.replace(/["\\]/g,'')}")`:'none','icon-width':[1.7,1.9,2.1][k.id%3]};if(s.customSurface){vars['accent-soft']=dark?'#263c33':'#e9f2ed'}if((Math.max(luminance(accent),luminance(surface))+.05)/(Math.min(luminance(accent),luminance(surface))+.05)<3){vars.accent=dark?'#a5efd4':'#12654f'}Object.entries(vars).forEach(([a,b])=>r.setProperty('--'+a,b));r.setProperty('--icon-cap',['round','round','square'][k.id%3]);r.setProperty('--icon-join',['round','round','miter'][k.id%3]);r.setProperty('--font',s.font==='serif'?"ZhiSerif,serif":s.font==='custom'?"ZhiCustom,ZhiSans,sans-serif":s.font==='system'?"-apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif":"ZhiSans,'PingFang SC','Microsoft YaHei',sans-serif");document.body.classList.remove('pixel','neon','glass','serif','clean');document.body.classList.add(k.style);document.documentElement.style.colorScheme=dark?'dark':'light';startParticles();}
function paintSkinPreview(){if(state.settings.font==='custom'&&!document.fonts.check('16px ZhiCustom'))toast('请先上传自定义字体；当前使用内置黑体。')}
function startParticles(){cancelAnimationFrame(particleFrame);const c=$('#particles'),x=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;x.clearRect(0,0,c.width,c.height);const s=state.settings;if(!s.particles||s.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const k=SKINS[s.theme],type=k.particle,items=Array.from({length:s.particleAmount},()=>({x:Math.random()*c.width,y:Math.random()*c.height,r:1+Math.random()*3,v:.2+Math.random()*.4,a:Math.random()*6.28}));let last=0;function frame(t){particleFrame=requestAnimationFrame(frame);if(document.hidden||t-last<32)return;last=t;x.clearRect(0,0,c.width,c.height);x.fillStyle=s.customAccent||k.accent;x.strokeStyle=x.fillStyle;items.forEach(p=>{p.y-=p.v*(1+k.id%4*.1);p.x+=Math.sin(t/3000+p.a)*.2;if(p.y< -15)p.y=c.height+10;x.save();x.translate(p.x,p.y);x.rotate(p.a+t/10000*(k.id%2?1:-1));x.globalAlpha=.15+(.1*(1+Math.sin(t/1500+p.a)));x.beginPath();if(type==='pixel')x.rect(-p.r,-p.r,p.r*2,p.r*2);else if(['leaf','petal'].includes(type))x.ellipse(0,0,p.r*2,p.r,0,0,Math.PI*2);else if(['star','cross','snow','spark'].includes(type)){x.moveTo(-p.r*2,0);x.lineTo(p.r*2,0);x.moveTo(0,-p.r*2);x.lineTo(0,p.r*2);if(type==='snow'){x.moveTo(-p.r,-p.r);x.lineTo(p.r,p.r)}x.stroke()}else if(type==='rain'){x.moveTo(0,0);x.lineTo(0,p.r*5);x.stroke()}else if(type==='ribbon'){x.moveTo(0,0);x.quadraticCurveTo(5,12,16,2);x.stroke()}else{x.arc(0,0,p.r,0,Math.PI*2);if(type==='bubble')x.stroke()}if(!['star','cross','snow','spark','rain','ribbon','bubble'].includes(type))x.fill();x.restore()});}particleFrame=requestAnimationFrame(frame)}
let audioCtx;function unlockAudio(){try{audioCtx ||= new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume()}catch{}}
function sound(correct,force=false){const s=state.settings;if(!force&&!(correct?s.soundRight:s.soundWrong))return;unlockAudio();if(!audioCtx)return;const kind=correct?s.rightSound:s.wrongSound,base=correct?({chime:[659,880,1318],piano:[523,659,784],arcade:[440,660,880,1320],water:[1200,800],space:[350,700,1400]}[kind]||[659,880]):({soft:[330,260],wood:[190,140],arcade:[360,240,120],low:[160,120],space:[700,350,175]}[kind]||[330,260]);base.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.095;o.type=kind==='arcade'?'square':kind==='wood'?'triangle':'sine';o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(s.volume*.13,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+.24);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+.25)})}
function download(data,name,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function pickFile(accept,fn){const i=document.createElement('input');i.type='file';i.accept=accept;i.onchange=()=>{if(i.files[0])Promise.resolve(fn(i.files[0])).catch(e=>toast(e.message||'文件读取失败'))};i.click()}
function modal(title,html,actions){const d=$('#modal');d.innerHTML=`<h2>${title}</h2>${html}<div class="modal-actions">${btn('取消','close-modal')}${actions||''}</div>`;d.showModal()}
function validateCfg(){const a=Number(cfg.from),b=Number(cfg.to),n=Number(cfg.count);if(!Number.isInteger(a)||!Number.isInteger(b)||a<1||b>BANK.length||a>b){toast(`请填写 1—${BANK.length} 内有效的起止题号。`);return false}if(!Number.isInteger(n)||n<1||n>BANK.length){toast('每组题数需为 1—2957 的整数。');return false}return true}
function start(mode=cfg.mode,egg='',explicit=null){unlockAudio();if(!explicit&&!validateCfg())return;clearInterval(timer);clearTimeout(autoTimer);let pool=explicit||filterBank(BANK,cfg,state.stats);if(mode==='review')pool=pool.filter(q=>qs(q.id).due&&qs(q.id).due<=Date.now()&&!qs(q.id).mastered);if(mode==='wrong')pool=pool.filter(q=>qs(q.id).wrong&&!qs(q.id).mastered);if(mode==='stars')pool=pool.filter(q=>qs(q.id).star);if(mode==='loop')pool=pool.filter(q=>!qs(q.id).mastered);if(mode==='exam'){const limits=[['single','单选'],['multiple','多选'],['judge','判断']];if(limits.some(([k])=>!Number.isInteger(+cfg[k])||+cfg[k]<0)||+cfg.examMinutes<1||+cfg.examMinutes>300){toast('请检查组卷题数与考试时长。');return}pool=limits.flatMap(([k,t])=>shuffle(pool.filter(q=>q.type===t)).slice(0,Number(cfg[k])));pool=shuffle(pool)}else if(mode==='random'||mode==='game'||mode==='quick'||cfg.shuffle||egg)pool=shuffle(pool);
let amount=Number(cfg.count);if(egg==='boss')pool=pool.filter(q=>qs(q.id).wrong>0).sort((a,b)=>qs(b.id).wrong-qs(a.id).wrong);if(egg==='reverse')pool.sort((a,b)=>b.id-a.id);if(egg==='relay'){const groups=DEPTS.map(d=>pool.filter(q=>q.dept===d)),arr=[];while(groups.some(g=>g.length))groups.forEach(g=>{if(g.length)arr.push(g.shift())});pool=arr}if(egg==='ladder')pool.sort((a,b)=>['判断','单选','多选'].indexOf(a.type)-['判断','单选','多选'].indexOf(b.type));if(egg==='new')pool=pool.filter(q=>!(qs(q.id).right+qs(q.id).wrong));if(egg==='repair')pool=pool.filter(q=>qs(q.id).last).sort((a,b)=>qs(a.id).last-qs(b.id).last);if(egg==='daily'){const seed=Number(dateKey().replaceAll('-',''));let rand=seed;pool=[...pool].sort((a,b)=>a.id-b.id);for(let i=pool.length-1;i>0;i--){rand=(Math.imul(rand,1664525)+1013904223)>>>0;const j=rand%(i+1);[pool[i],pool[j]]=[pool[j],pool[i]]}amount=10}if(egg==='marathon')amount=100;if(egg==='pair')amount=3;if(['sprint','pomo','streak'].includes(egg))amount=Math.max(100,amount);if(mode!=='exam'&&!explicit)pool=pool.slice(0,amount);if(!pool.length){toast(mode==='review'?'当前范围没有到期题目，可去记忆计划查看安排。':mode==='loop'?'当前范围题目已全部掌握。':'当前条件下没有可练习的题目，请调整范围。');return}
const now=Date.now();session={mode,egg,ids:pool.map(q=>q.id),baseIds:pool.map(q=>q.id),index:0,answers:{},selected:[],revealed:false,hidden:egg==='blind',confidence:null,started:now,questionStarted:now,questionDeadline:now+Number(state.settings.quickSeconds)*1000,endAt:mode==='exam'?now+Number(cfg.examMinutes)*60000:egg==='sprint'?now+60000:egg==='pomo'?now+25*60000:0,done:false,attempts:0,right:0,streak:0,maxStreak:0,lives:3,xp:0,order:{},notesOpen:false,waiting:false,trail:[],queue:[],pairLeft:null,pairDone:[],pairChoices:shuffle(pool.map(q=>q.id)),pairWrong:[],flags:{},historySaved:false};if(mode==='loop'){const due=pool.filter(q=>!qs(q.id).due||qs(q.id).due<=now);session.ids=due.length?due.map(q=>q.id):pool.map(q=>q.id);session.waiting=!due.length}persistSession();navigate('study');}
function current(){return BANK[session.ids[session.index]-1]}
function sessionName(){return session.egg?EGGS.find(e=>e[0]===session.egg)?.[1]:MODES.find(m=>m[0]===session.mode)?.[1]||({wrong:'错题重练',stars:'收藏练习'}[session.mode]||'专项练习')}
function persistSession(){try{localStorage.setItem('zhiyi.session',JSON.stringify(session));localStorage.setItem('zhiyi.cfg',JSON.stringify(cfg))}catch{}}
function getOptions(q){if(!session.order[q.id]){session.order[q.id]=(state.settings.optionShuffle&&q.type!=='判断'?shuffle(q.options):q.options).map(o=>o.key)}return session.order[q.id].map(k=>q.options.find(o=>o.key===k))}
function study(){if(!session)return practice();if(session.done)return result();if(session.waiting)return loopWait();if(session.egg==='pair')return pairView();const q=current();if(!q){finish();return result()}const s=qs(q.id),exam=session.mode==='exam',read=session.mode==='read',flash=session.mode==='flash',saved=session.answers[session.index],revealed=read||session.revealed||(!exam&&!!saved),selected=exam?(saved?.selected||session.selected):session.selected.length?session.selected:saved?.selected||[],correct=saved?.correct,options=getOptions(q),isEliminate=session.egg==='eliminate';return`${heading(sessionName(),`${q.dept} · ${q.type} · 原表题号 ${q.sourceId} · 全库 ${q.id}`,`<div class="inline">${btn(`${icon('expand')} 专注`,'focus')}${btn('结束练习','end-session')}</div>`,'ONE QUESTION AT A TIME')}<div class="study-layout"><div><div class="panel question-panel">${session.egg||session.mode==='game'?gameBanner():''}<div class="question-meta"><div class="inline"><span class="tag">${q.type}</span><span class="small muted">第 ${session.index+1} / ${session.ids.length} 题</span></div><div class="inline">${session.mode==='quick'||session.endAt||session.egg==='slow'?'<span id="timer-display" class="timer"></span>':''}<button class="btn icon-only" data-star="${q.id}" aria-label="${s.star?'取消收藏':'收藏'}" style="color:${s.star?'var(--accent)':'var(--muted)'}">${icon('star')}</button></div></div><div class="progress-track"><div class="progress-fill" style="width:${pct(session.index+1,session.ids.length)}%"></div></div><h2 class="question-title">${esc(q.text)}</h2>${isEliminate?'<div class="note-banner">请选择所有错误选项。若全部选项都正确，可不选直接提交。</div>':''}${session.egg==='confidence'&&!saved?`<div class="inline" style="margin-bottom:20px"><span class="small muted">我对这道题：</span>${[['high','很确定'],['medium','有点把握'],['low','不太确定']].map(([v,t])=>`<button class="mode-tab ${session.confidence===v?'active':''}" data-confidence="${v}">${t}</button>`).join('')}</div>`:''}${session.hidden&&!revealed?`<div class="flash-answer"><p>先在心中回忆，再看选项。</p>${btn('展开选项','reveal-options','primary','style="margin-top:15px"')}</div>`:flash&&!revealed?`<div class="flash-answer"><p>试着说出正确答案。</p>${btn(`${icon('layers')} 翻开闪卡`,'flip','primary','style="margin-top:18px"')}</div>`:`<div class="options">${options.map((o,i)=>{const label=String.fromCharCode(65+i),isAnswer=q.answer.includes(o.key),chosen=selected.includes(o.key);return`<button class="option ${chosen?'selected':''} ${revealed&&isAnswer?'correct':''} ${revealed&&chosen&&!isAnswer&&!isEliminate?'wrong':''}" data-option="${o.key}" ${revealed||read?'disabled':''} style="${revealed?'opacity:1;cursor:default':''}"><span class="option-letter">${q.type==='判断'?icon(o.key==='A'?'check':'close'):label}</span><span>${esc(o.text)}</span>${revealed&&isAnswer?`<span style="margin-left:auto">${icon('check')}</span>`:''}</button>`}).join('')}</div>`}${revealed?`<div class="answer-box ${correct===false?'wrong':''}"><strong>${read?'答案速记':flash?'参考答案':correct===false?'再巩固一次':correct===true?'回答正确':'参考答案'} · ${answerLabel(q,options)}</strong><p>${q.options.filter(o=>q.answer.includes(o.key)).map(o=>esc(o.text)).join('；')}</p>${read||flash?'':'<p>本题没有原始解析，可在右侧写下你的理解。</p>'}${s.due?`<p>下一次间隔复习：${fmtDue(s.due)}${s.stage?' · 第 '+s.stage+' 阶段':''}</p>`:''}</div>`:''}${flash&&revealed&&!saved?`<div class="inline" style="margin-top:20px">${btn('还没记住','flash-wrong')}${btn('已经记住','flash-right','primary')}</div>`:''}<div class="study-actions">${btn(`${icon('back')} 上一题`,'prev','',session.index===0?'disabled':'')}<div class="inline">${!revealed&&!flash?btn(exam?'保存并下一题':q.type==='多选'||isEliminate?'确认选择':'提交答案','submit','primary'):!flash||saved?btn(`${session.index===session.ids.length-1&&session.mode!=='loop'?'完成练习':'下一题'} ${icon('arrow')}`,'next','primary'):''}${exam?btn('交卷','end-session','soft'):''}</div></div></div><p class="kbd-hint">A–F 选择选项 · Enter 提交 / 下一题 · S 收藏 · Shift+F 专注</p></div><div class="stack"><section class="panel"><div class="panel-title"><h2>答题卡</h2><span class="small muted">${Object.keys(session.answers).length}/${session.ids.length}</span></div><div class="filters" style="margin-bottom:13px"><input class="search" id="session-jump" placeholder="题序 / 全库编号" aria-label="答题卡跳转"><button class="btn icon-only" data-action="session-jump" aria-label="跳转">${icon('arrow')}</button></div><div class="answer-grid">${session.ids.map((id,i)=>`<button class="answer-number ${i===session.index?'current':''} ${session.answers[i]?(exam?'ok':session.answers[i].correct?'ok':'bad'):''}" data-jump="${i}" title="第 ${i+1} 题 · 全库编号 ${id}">${i+1}</button>`).join('')}</div><div class="legend"><span><i class="green"></i>${exam?'已答':'答对'}</span>${exam?'':'<span><i class="red"></i>答错</span>'}<span><i></i>未答</span></div></section><section class="panel"><h2>这道题的足迹</h2><div class="q-stats"><span class="muted">累计答对</span><strong>${s.right} 次</strong></div><div class="q-stats"><span class="muted">累计答错</span><strong>${s.wrong} 次</strong></div><div class="q-stats"><span class="muted">正确率</span><strong>${s.right+s.wrong?pct(s.right,s.right+s.wrong)+'%':'—'}</strong></div><div class="q-stats"><span class="muted">记忆阶段</span><strong>${s.mastered?'已掌握':s.stage+' / 8'}</strong></div><label class="field" style="margin-top:17px">我的记忆笔记<textarea class="notes" data-note="${q.id}" placeholder="写下易错点、口诀或自己的理解…">${esc(s.note)}</textarea></label><p class="small muted" style="margin-top:7px">离开输入框时自动保存</p></section>${session.mode==='loop'?`<section class="panel review-box"><h3>循环攻克中</h3><p class="small" style="margin-top:8px">${session.baseIds.filter(id=>qs(id).mastered).length} / ${session.baseIds.length} 题已掌握。短时重练不会跳过记忆阶段。</p></section>`:''}</div></div>`}
function answerLabel(q,options=q.options){return options.map((o,i)=>q.answer.includes(o.key)?q.type==='判断'?o.text:String.fromCharCode(65+i):'').filter(Boolean).join('、')}
function gameBanner(){let text=EGGS.find(e=>e[0]===session.egg)?.[3]||'三次失误机会，每五题晋升一关。';return`<div class="game-banner"><span>${icon(EGGS.find(e=>e[0]===session.egg)?.[2]||'game')} ${text}</span><span>${session.mode==='game'?'第 '+(Math.floor(session.right/5)+1)+' 关 · ':''}连击 ${session.streak} · 积分 ${session.xp}${session.mode==='game'||session.egg==='survival'?' · 生命 '+session.lives:''}</span></div>`}
function choose(key){if(session.done||session.revealed||session.waiting||session.mode==='read'||session.mode==='flash')return;if(session.egg==='slow'&&Date.now()-session.questionStarted<8000){toast('先读完这八秒，再作答。');return}if(session.answers[session.index]&&session.mode!=='exam')return;const q=current();if(q.type==='多选'||session.egg==='eliminate'){session.selected=session.selected.includes(key)?session.selected.filter(k=>k!==key):[...session.selected,key]}else session.selected=[key];if(session.mode==='exam')session.answers[session.index]={selected:[...session.selected]};render();persistSession();if(session.mode==='quick'&&q.type!=='多选')submit()}
function record(q,correct){state.stats[q.id]=grade(qs(q.id),correct);const day=dateKey();state.days[day]||={count:0,right:0};state.days[day].count++;if(correct)state.days[day].right++;session.attempts++;if(correct){session.right++;session.streak++;session.xp+=10+Math.min(10,session.streak)}else{session.streak=0;session.lives--}session.maxStreak=Math.max(session.maxStreak,session.streak);session.trail.push({id:q.id,correct,time:Date.now()});save();sound(correct)}
function submit(timeout=false,self=null){if(!session||session.done||session.waiting)return;const q=current(),exam=session.mode==='exam';if(!exam&&session.answers[session.index]){next();return}if(session.egg==='slow'&&Date.now()-session.questionStarted<8000&&!timeout){toast('请先阅读 8 秒。');return}if(!timeout&&self===null&&!session.selected.length&&session.egg!=='eliminate'){toast('请先选择答案。');return}if(session.egg==='confidence'&&!session.confidence&&!timeout){toast('先标记一下你的把握程度。');return}if(exam){session.answers[session.index]={selected:[...session.selected]};persistSession();next();return}let correct=self!==null?self:checkAnswer(q,session.selected);if(session.egg==='eliminate')correct=checkAnswer({...q,answer:q.options.filter(o=>!q.answer.includes(o.key)).map(o=>o.key).sort().join('')},session.selected);if(timeout&&!session.selected.length)correct=false;session.answers[session.index]={selected:[...session.selected],correct,confidence:session.confidence,timeout};record(q,correct);session.revealed=true;if(session.egg==='spaced'&&!correct)session.queue.push({id:q.id,after:session.attempts+3});persistSession();render();if((session.mode==='game'||session.egg==='survival')&&session.lives<=0){scheduleFinish('三次机会用完了，休息一下再挑战。');return}if(session.egg==='precision'&&!correct){scheduleFinish('这次的满分守护结束了。');return}if(session.egg==='streak'&&session.streak>=10){scheduleFinish('十连击达成！');return}if(session.mode==='quick'){scheduleNext(state.settings.quickReveal)}else if(state.settings.autoNext&&!['flash','read'].includes(session.mode))scheduleNext(state.settings.autoDelay)}
function scheduleNext(seconds){clearTimeout(autoTimer);session.autoAt=Date.now()+Number(seconds)*1000;autoTimer=setTimeout(()=>{if(view==='study'&&!session.done)next()},Number(seconds)*1000)}
function scheduleFinish(reason){clearTimeout(autoTimer);session.finishReason=reason;autoTimer=setTimeout(()=>{if(view==='study')finish()},1500)}
function move(index){clearTimeout(autoTimer);session.autoAt=0;session.index=index;session.selected=[...(session.answers[index]?.selected||[])];session.revealed=session.mode!=='exam'&&!!session.answers[index];session.hidden=session.egg==='blind';session.confidence=session.answers[index]?.confidence||null;session.questionStarted=Date.now();session.questionDeadline=Date.now()+Number(state.settings.quickSeconds)*1000;persistSession();render()}
function next(){if(!session||session.done)return;clearTimeout(autoTimer);if(session.mode==='exam'&&session.selected.length)session.answers[session.index]={selected:[...session.selected]};if(session.egg==='spaced'){const ready=session.queue.filter(q=>q.after<=session.attempts);ready.forEach(q=>session.ids.splice(session.index+1,0,q.id));session.queue=session.queue.filter(q=>q.after>session.attempts)}if(session.egg==='dice'){const candidates=session.ids.map((id,i)=>i).filter(i=>!session.answers[i]&&i!==session.index);if(candidates.length){move(shuffle(candidates)[0]);return}finish();return}if(session.index+1<session.ids.length){move(session.index+1);return}if(session.mode==='exam'){confirmFinish();return}if(session.mode==='loop'){const pool=session.baseIds.filter(id=>!qs(id).mastered);if(!pool.length){session.finishReason='当前范围已全部掌握！';finish();return}const ready=pool.filter(id=>!qs(id).due||qs(id).due<=Date.now());session.ids=ready.length?ready:pool;session.answers={};session.index=0;session.waiting=!ready.length;move(0);return}if(session.egg==='spaced'&&session.queue.length){const item=session.queue[0],others=session.baseIds.filter(id=>id!==item.id);if(others.length){const needed=Math.max(0,item.after-session.attempts);session.ids.push(...Array.from({length:needed},(_,i)=>others[i%others.length]));if(!needed){session.ids.push(item.id);session.queue.shift()}move(session.index+1);return}else{session.finishReason='这组只有一题，错题已进入间隔复习计划。'}}finish()}
function confirmFinish(){if(!session||session.done)return;const unanswered=session.ids.length-Object.keys(session.answers).length;modal(session.mode==='exam'?'确认交卷？':'结束这次练习？',`<p>${session.mode==='exam'?`还有 ${unanswered} 题未作答，交卷后未答题按错误计分。`:'已经完成的作答记录会保留，你也可以之后重新练习。'}</p>`,btn(session.mode==='exam'?'交卷并评分':'结束并查看结果','finish-confirm','primary'))}
function finish(){clearInterval(timer);clearTimeout(autoTimer);if(!session||session.done)return;if(session.mode==='exam'){session.ids.forEach((id,i)=>{const q=BANK[id-1],a=session.answers[i]||{selected:[]};a.correct=checkAnswer(q,a.selected);record(q,a.correct);session.answers[i]=a})}session.done=true;session.finished=Date.now();if(!session.historySaved){state.history.unshift({name:sessionName(),time:Date.now(),right:session.right,total:session.attempts,duration:Date.now()-session.started});state.history=state.history.slice(0,150);session.historySaved=true;save()}persistSession();render();window.scrollTo(0,0)}
function result(){const s=session,read=s.mode==='read',wrong=s.trail.filter(a=>!a.correct);return`${heading('把这一刻的进步，记下来。','','','SESSION COMPLETE')}<section class="panel session-result">${icon('flag')}<h2 style="margin-top:15px">${s.finishReason||'这段学习完成了'}</h2><p class="muted small" style="margin-top:9px">${sessionName()} · ${Math.max(1,Math.round(((s.finished||Date.now())-s.started)/60000))} 分钟</p><div class="result-score">${read?'完成':pct(s.right,s.attempts)}${read?'':'<small>%</small>'}</div><p class="muted small">${read?'背题浏览不计入作答正确率':'本次正确率'}</p><div class="result-grid"><div><strong>${s.attempts}</strong><span>累计作答</span></div><div><strong>${s.right}</strong><span>答对</span></div><div><strong>${s.maxStreak}</strong><span>最高连击</span></div></div>${s.egg==='confidence'?`<p class="small muted" style="margin-bottom:20px">高信心答错 ${Object.values(s.answers).filter(a=>a.confidence==='high'&&!a.correct).length} 题 · 这些题值得特别复习。</p>`:''}<div class="inline" style="justify-content:center">${btn('回到学习空间','goto-home')}${wrong.length?btn('只练本次错题','retry-wrong','primary'):btn('再来一组','restart','primary')}</div></section>${wrong.length?`<section class="panel"><h2>本次需要巩固</h2>${[...new Set(wrong.map(w=>w.id))].map(id=>{const q=BANK[id-1];return`<div class="list-line"><button class="text-button" data-start-id="${id}"><span class="tag">${id}</span> ${esc(q.text)}</button><span class="small muted">${answerLabel(q)}</span></div>`}).join('')}</section>`:''}`}
function loopWait(){const remaining=session.baseIds.filter(id=>!qs(id).mastered),nextDue=Math.min(...remaining.map(id=>qs(id).due||Date.now()));return`${heading('让这一轮记忆沉淀一下。','循环计划已保存，到期后继续复习。','','LOOP & REMEMBER')}<section class="panel session-result">${icon('brain')}<h2 style="margin-top:20px">本轮已完成，下一次${fmtDue(nextDue)}</h2><p class="muted" style="margin-top:14px">${session.baseIds.length-remaining.length} / ${session.baseIds.length} 题已掌握<br>仍有 ${remaining.length} 题等待后续间隔巩固。</p><div class="inline" style="justify-content:center;margin-top:28px">${btn('检查到期题','loop-check','primary')}${btn('提前强化一轮','loop-force')}${btn('返回首页','goto-home')}</div><p class="small muted" style="margin-top:20px">提前练习可以计入作答次数，但不会提前推进阶段。应用需再次打开后检查到期，不会发送后台通知。</p></section>`}
function pairView(){return`${heading('让问题，找到答案。','先选左侧题目，再选右侧正确答案内容。',btn('结束练习','end-session'),'MATCH & REMEMBER')}<section class="panel"><div class="game-banner"><span>配对成功 ${session.pairDone.length} / ${session.ids.length}</span><span>积分 ${session.xp}</span></div><div class="match-grid"><div class="stack">${session.ids.map(id=>{const q=BANK[id-1];return`<button class="${session.pairLeft===id?'chosen':''} ${session.pairDone.includes(id)?'matched':''}" data-pair-left="${id}" ${session.pairDone.includes(id)?'disabled':''}><span class="tag">${id}</span><p style="margin-top:10px">${esc(q.text)}</p></button>`}).join('')}</div><div class="stack">${session.pairChoices.map(id=>{const q=BANK[id-1];return`<button class="${session.pairDone.includes(id)?'matched':''}" data-pair-right="${id}" ${session.pairDone.includes(id)?'disabled':''}>${esc(q.options.filter(o=>q.answer.includes(o.key)).map(o=>o.text).join('；'))}</button>`}).join('')}</div></div></section>`}
function pairAnswer(id){if(!session.pairLeft){toast('先选择左侧题目。');return}const q=BANK[session.pairLeft-1],r=BANK[id-1],text=q=>q.options.filter(o=>q.answer.includes(o.key)).map(o=>o.text).join('；'),ok=text(q)===text(r);record(q,ok);if(ok){session.pairDone.push(session.pairLeft);const index=session.pairChoices.indexOf(id),leftIndex=session.pairChoices.indexOf(session.pairLeft);[session.pairChoices[index],session.pairChoices[leftIndex]]=[session.pairChoices[leftIndex],session.pairChoices[index]];session.pairLeft=null;if(session.pairDone.length===session.ids.length){finish();return}}else toast('配对还不对，再想一想。');persistSession();render()}
function startTimer(){clearInterval(timer);if(!session||session.done||session.waiting)return;function tick(){if(view!=='study'||session.done)return;let seconds=null;if(session.endAt){seconds=Math.ceil((session.endAt-Date.now())/1000);if(seconds<=0){session.finishReason=session.mode==='exam'?'考试时间到，已自动交卷。':session.egg==='pomo'?'专注 25 分钟，休息 5 分钟吧。':'60 秒冲刺完成！';$('#modal').close();finish();return}}else if(session.mode==='quick'&&!session.revealed&&!session.answers[session.index]){seconds=Math.ceil((session.questionDeadline-Date.now())/1000);if(seconds<=0){submit(true);return}}else if(session.egg==='slow'&&!session.revealed){seconds=Math.max(0,8-Math.floor((Date.now()-session.questionStarted)/1000));}const el=$('#timer-display');if(el){el.innerHTML=seconds===null?'':icon('clock')+(seconds>60?`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`:`${seconds}s`);el.classList.toggle('urgent',seconds!==null&&seconds<=5)}if(session.autoAt&&Date.now()>=session.autoAt){session.autoAt=0;next()}}tick();timer=setInterval(tick,250)}
const numericSettings={fontSize:[16,30],particleAmount:[8,80],glow:[0,1],brightness:[.65,1.15],bgOpacity:[0,.8],volume:[0,1],goal:[1,2000],autoDelay:[1,30],quickSeconds:[2,120],quickReveal:[1,30]};
function changeSetting(el){const k=el.dataset.setting;let v=el.type==='checkbox'?el.checked:el.value;if(numericSettings[k]){v=Number(v);if(!Number.isFinite(v))return;v=Math.max(numericSettings[k][0],Math.min(numericSettings[k][1],v));if(['fontSize','particleAmount','goal','autoDelay','quickSeconds','quickReveal'].includes(k))v=Math.round(v)}if(k==='font'&&v==='custom'&&!customFontLoaded){toast('请先上传自定义字体文件。');el.value=state.settings.font;return}state.settings[k]=v;save();if(['theme','font','fontSize','particles','particleAmount','glow','brightness','bgOpacity','reduceMotion','customAccent','customBg','customSurface'].includes(k))applyTheme();if(k==='fontSize'&&$('#fontSize-label'))$('#fontSize-label').textContent=v;}
function setMode(mode){cfg.mode=mode;navigate('practice')}
function validateBackup(x){if(!x||x.app!=='zhiyi'||x.version!==1||!x.data||typeof x.data.stats!=='object'||Array.isArray(x.data.stats))throw Error('这不是有效的知一学习备份。');const data=x.data,clean={stats:{},days:{},history:[],settings:{...defaults}};for(const [id,s]of Object.entries(data.stats)){if(!BANK[+id-1]||!s||typeof s!=='object')throw Error('题目记录格式无效。');const numbers=['right','wrong','stage','due','last','streak'];if(numbers.some(k=>!Number.isFinite(s[k])||s[k]<0)||s.stage>8)throw Error('作答统计值无效。');clean.stats[id]={...fresh(),...Object.fromEntries(numbers.map(k=>[k,s[k]])),mastered:!!s.mastered,star:!!s.star,note:String(s.note||'').slice(0,10000)}}for(const [d,s]of Object.entries(data.days||{})){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!s||!Number.isFinite(s.count)||!Number.isFinite(s.right)||s.count<0||s.right<0||s.right>s.count)throw Error('每日统计格式无效。');clean.days[d]={count:s.count,right:s.right}}clean.history=(Array.isArray(data.history)?data.history:[]).filter(h=>typeof h.name==='string'&&[h.time,h.right,h.total,h.duration].every(v=>Number.isFinite(v)&&v>=0)).slice(0,150);clean.settings=sanitizeSettings(data.settings||{});return clean}
function sanitizeSettings(input){const s={...defaults};for(const k of Object.keys(defaults)){const v=input[k];if(v===undefined)continue;if(numericSettings[k]){if(Number.isFinite(v))s[k]=Math.max(numericSettings[k][0],Math.min(numericSettings[k][1],v));}else if(typeof defaults[k]==='boolean')s[k]=v===true;else if(['customAccent','customBg','customSurface'].includes(k))s[k]=/^#[\da-f]{6}$/i.test(v)?v:'';else if(k==='background')s[k]=typeof v==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(v)&&v.length<3000000?v:'';else if(k==='theme')s[k]=Number.isInteger(v)&&SKINS[v]?v:0;else if(k==='font')s[k]=['sans','serif','system','custom'].includes(v)?v:'sans';else if(k==='rightSound')s[k]=['chime','piano','arcade','water','space'].includes(v)?v:'chime';else if(k==='wrongSound')s[k]=['soft','wood','arcade','low','space'].includes(v)?v:'soft'}return s}
let pendingBackup=null,customFontLoaded=false;async function fontDB(mode,key,value){return new Promise((resolve,reject)=>{const request=indexedDB.open('zhiyi.assets',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('assets',mode==='get'?'readonly':'readwrite'),s=tx.objectStore('assets'),r=mode==='get'?s.get(key):s.put(value,key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);tx.oncomplete=()=>db.close()}})}
