function startAt(id){start('sequence','',BANK.slice(id-1,Math.min(BANK.length,id-1+Number(cfg.count))))}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b||b.disabled)return;if(b.dataset.nav){navigate(b.dataset.nav);return}if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.mode){setMode(b.dataset.mode);return}if(b.dataset.configMode){cfg.mode=b.dataset.configMode;render();return}if(b.dataset.dept){cfg.dept=b.dataset.dept;cfg.from=1;cfg.to=BANK.filter(q=>q.dept===cfg.dept).length;cfg.numbering='department';cfg.mode='department';navigate('practice');return}if(b.dataset.startId){startAt(Number(b.dataset.startId));return}if(b.dataset.option){choose(b.dataset.option);return}if(b.dataset.jump!==undefined){move(Number(b.dataset.jump));return}if(b.dataset.star){const id=b.dataset.star;state.stats[id]={...qs(id),star:!qs(id).star};save();render();return}if(b.dataset.egg){start('egg',b.dataset.egg);return}if(b.dataset.confidence){session.confidence=b.dataset.confidence;render();return}if(b.dataset.skin){state.settings.theme=Number(b.dataset.skin);state.settings.customAccent='';state.settings.customBg='';state.settings.customSurface='';save();applyTheme();render();return}if(b.dataset.skinCategory){skinCategory=b.dataset.skinCategory;render();return}if(b.dataset.pairLeft){session.pairLeft=Number(b.dataset.pairLeft);render();return}if(b.dataset.pairRight){pairAnswer(Number(b.dataset.pairRight));return}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.cfg){cfg[el.dataset.cfg]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.dataset.cfg==='dept'&&cfg.numbering!=='global'){cfg.from=1;cfg.to=cfg.dept==='全部部门'?BANK.length:BANK.filter(q=>q.dept===cfg.dept).length}if(['dept','type','numbering'].includes(el.dataset.cfg))render();persistSession()}if(el.dataset.setting)changeSetting(el);if(el.dataset.filter){bankFilter[el.dataset.filter]=el.value;bankPage=1;render()}if(el.dataset.note){state.stats[el.dataset.note]={...qs(el.dataset.note),note:el.value.slice(0,10000)};save()}});
