document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('focus');if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){if(e.key==='Enter'&&e.target.id==='bank-search')actions['bank-search']();if(e.key==='Enter'&&e.target.id==='skin-search')actions['skin-search']();return}if($('#modal').open||view!=='study'||!session||session.done||session.waiting||session.egg==='pair')return;if(e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key.toUpperCase();if(/^[A-F]$/.test(k)&&k!=='F'){const o=getOptions(current())[k.charCodeAt(0)-65];if(o)choose(o.key);e.preventDefault()}else if(k==='F'){if(current().options.length>=6&&!e.shiftKey){choose(getOptions(current())[5].key)}else document.body.classList.toggle('focus');e.preventDefault()}else if(k==='ENTER'){e.preventDefault();if(session.mode==='read')next();else if(session.mode==='flash'){if(!session.revealed){session.revealed=true;render()}else if(session.answers[session.index])next()}else if(session.revealed)next();else submit()}else if(k==='S'){state.stats[current().id]={...qs(current().id),star:!qs(current().id).star};save();render()}else if(k==='ARROWRIGHT'){e.preventDefault();next()}else if(k==='ARROWLEFT'&&session.index>0){e.preventDefault();move(session.index-1)}});
window.addEventListener('resize',()=>{applyDevice();startParticles()});
