async function init(){try{const r=await fetch(new URL('./questions.json',import.meta.url));if(!r.ok)throw Error('题库读取失败');BANK=await r.json();DEPTS=[...new Set(BANK.map(q=>q.dept))];state.settings=sanitizeSettings(state.settings);try{const c=JSON.parse(localStorage.getItem('zhiyi.cfg'));if(c)cfg={...cfg,...c};const s=JSON.parse(localStorage.getItem('zhiyi.session'));if(s&&Array.isArray(s.ids)&&s.ids.every(id=>BANK[id-1])&&s.baseIds?.every(id=>BANK[id-1])&&!s.done)session=s}catch{}applyTheme();render();try{const font=await fontDB('get','font');if(font)await loadCustomFont(font)}catch{}if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('./sw.js',import.meta.url)).catch(()=>{});registerTools()}catch(e){$('#app').innerHTML=`<div class="empty"><h2>题库暂时没有加载成功</h2><p>请检查网络连接后刷新页面。</p><button class="btn primary" onclick="location.reload()">重新加载</button></div>`;console.error(e)}}
